mapper.select:
select * from ( select ID, TWINING_DISC_CODE, TWINING_DISC_NAME, STATUS, PRO_SIZE, QTY, IS_DELETE, CREATE_BY, CREATE_TIME, UPDATE_BY, UPDATE_TIME, REMARK from T_GSQ_TWINING_DISC where IS_DELETE = '0'
and INSTR(TWINING_DISC_CODE, #{twiningDiscCode}) > 0
and INSTR(TWINING_DISC_NAME, #{twiningDiscName}) > 0
and STATUS = #{status}
order by CREATE_TIME desc
) t
order by ${orderStr}

select count(1)
from T_GSQ_TWINING_DISC
where IS_DELETE = '0'
  and TWINING_DISC_CODE = #{twiningDiscCode}

    and ID != #{id}
